const upsertUserCredential = `-- name: UpsertUserCredential :exec
INSERT INTO user_credentials (
    user_id,
    password_hash,
    password_changed_at,
    failed_login_count,
    locked_until
) VALUES (
    $1, $2, $3, 0, NULL
)
ON CONFLICT (user_id) DO UPDATE
SET password_hash = EXCLUDED.password_hash,
    password_changed_at = EXCLUDED.password_changed_at,
    failed_login_count = 0,
    locked_until = NULL
`

type UpsertUserCredentialParams struct {
	UserID            uuid.UUID `json:"user_id"`
	PasswordHash      string    `json:"password_hash"`
	PasswordChangedAt time.Time `json:"password_changed_at"`
}

func (q *Queries) UpsertUserCredential(ctx context.Context, arg UpsertUserCredentialParams) error {
	_, err := q.db.Exec(ctx, upsertUserCredential, arg.UserID, arg.PasswordHash, arg.PasswordChangedAt)
	return err
}
